    /// <summary>
    /// Bug 99700
    /// Computed column to select description of METCustomerOperationsGroup
    /// </summary>
    /// <returns>description</returns>
    private static server str getMETCustomerOperationsGroupDescription()
    {
        METCustOperGroupId  custOperGroupId;        
        
        //table to select from
        SysDictTable      METCustomerOperationsGroup = new SysDictTable(tableNum(METCustomerOperationsGroup));

        
        //custOperGroupId is the field from the Entity
        custOperGroupId = SysComputedColumn::returnField(dataentityviewstr(CustCustomerDetailV2Entity),
                                                        dataEntityDataSourceStr(CustCustomerDetailV2Entity, METCustTable),
                                                        fieldStr(METCustTable, CustOperGroupId));  

        // Query shown below
        // select TOP 1 description from METCustomerOperationsGroup where METCustomerOperationsGroup.CustomerOperationsGroup == custOperGroupId <some value>
        return strFmt('SELECT %2 FROM %1 WHERE %1.%3 = %4',
            METCustomerOperationsGroup.name(DbBackend::Sql),
            METCustomerOperationsGroup.fieldName(fieldNum(METCustomerOperationsGroup, description), DbBackend::Sql),
            METCustomerOperationsGroup.fieldName(fieldNum(METCustomerOperationsGroup, CustomerOperationsGroup), DbBackend::Sql),
            custOperGroupId);
        
    }
